def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = opp.count('D')
    my_d = my.count('D')
    opp_c = n - opp_d

    if n == 50:
        if opp_d == 0 and my_d == 0:
            return 'D'

    if 51 <= n <= 54:
        if len(history) > 50 and my[50] == 'D':
            return 'C'

    if n >= 55 and opp_d == 0:
        return 'D'

    last_my, last_opp = history[-1]

    if opp_c == 0:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            return 'D'
        if opp_d <= 2:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if last_my == 'D':
            return 'C'
        if opp_d > n * 0.5:
            return 'D' if rng.random() < 0.5 else 'C'
        if opp_d > n * 0.3:
            return 'D' if rng.random() < 0.2 else 'C'
        return 'C'

    return 'C'
